function reviewSection(p){const real=(Array.isArray(productReviews[p.id])?productReviews[p.id]:[]).filter(r=>r&&Number.isInteger(r.rating)&&r.rating>=1&&r.rating<=5&&typeof r.text==='string').slice(0,30);const demos=CHAMEA_DEMO_REVIEWS.map((r,i)=>({...r,text:r.text.replace(/thiết kế/gi,'thiết kế '+p.family).replace(/màu này/gi,'màu '+p.color.toLowerCase()+' này')}));const demoAvg=(demos.reduce((n,r)=>n+r.rating,0)/demos.length).toFixed(1);return `<section class="section chamea-reviews" id="reviews"><div class="chamea-review-head"><div><p class="eyebrow">GÓC CHIA SẺ VỀ THIẾT KẾ</p><h2>Review &amp; Comment</h2><p class="chamea-review-intro">Cảm nhận về ${esc(p.name)} · <strong>Đánh giá minh họa</strong> — nội dung giả định, không phải phản hồi từ người đã mua hàng.</p></div><div class="chamea-review-overview"><div class="chamea-review-stars" aria-label="${demoAvg} trên 5 sao minh họa">★★★★★</div><strong>${demoAvg}/5 <span class="chamea-demo-tag">Đánh giá minh họa</span></strong><span>${demos.length} nhận xét mẫu · Không phải đánh giá mua hàng thực tế</span></div></div><div class="chamea-review-layout"><div class="chamea-review-list"><div class="chamea-review-demo-note">Các bình luận bên dưới là <strong>đánh giá minh họa</strong> được biên soạn để giới thiệu giao diện và phong cách sản phẩm. Không phải trải nghiệm mua hàng đã được xác minh.</div>${demos.map(r=>`<article class="chamea-review-item"><div class="chamea-review-meta"><strong>${esc(r.name)} <small class="chamea-demo-tag">Minh họa</small></strong><span>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${esc(r.text)}</p><small>${esc(r.date)} · Đánh giá minh họa</small></article>`).join('')}${real.length?`<h3 class="chamea-local-review-heading">Nhận xét bạn đã lưu trên thiết bị này</h3>${real.map(r=>`<article class="chamea-review-item"><div class="chamea-review-meta"><strong>${esc(r.name||'Khách hàng')}</strong><span>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${esc(r.text).replace(/\\n/g,'<br>')}</p><small>${esc(r.date||'')} · Chỉ lưu trên thiết bị này</small></article>`).join('')}`:""}</div><form class="chamea-review-form" data-form="product-review" data-product-id="${esc(p.id)}"><h3>Viết đánh giá của bạn</h3><p>Chia sẻ cảm nhận để tham khảo.</p><label>Đánh giá <select name="rating" required><option value="5">★★★★★ · 5 sao</option><option value="4">★★★★☆ · 4 sao</option><option value="3">★★★☆☆ · 3 sao</option><option value="2">★★☆☆☆ · 2 sao</option><option value="1">★☆☆☆☆ · 1 sao</option></select></label><label>Tên hiển thị <input name="name" maxlength="45" required placeholder="Tên của bạn"></label><label>Nhận xét <textarea name="text" maxlength="800" minlength="10" rows="5" required placeholder="Bạn cảm nhận thế nào về thiết kế này?"></textarea></label><button class="btn" type="submit">Gửi đánh giá</button><p class="chamea-review-disclaimer">Bản thử nghiệm: đánh giá của bạn chỉ lưu trên trình duyệt này, chưa hiển thị cho khách hàng khác và không được tính vào điểm minh họa.</p></form></div></section>`}

