 const entries=[
 ['Baguette – Nét thanh lịch mang hơi thở hiện đại','lune','Lune','Túi Baguette có dáng ngang thuôn dài và quai đeo vai gọn gàng, gợi cảm hứng thời trang cuối thập niên 1990. CHAMÉA Lune sắc burgundy kết hợp phom mềm mại với khóa kim loại ánh vàng, mang vẻ đẹp cổ điển mà hiện đại.','Phối cùng sơ mi trắng, jeans ống đứng và giày cao gót; hoặc váy liền thân và giày búp bê.','Minimalism, Quiet Luxury và Casual Chic.'],
 ['Top Handle – Vẻ đẹp nữ tính và sang trọng','nina','Nina','Túi Top Handle nổi bật với quai xách tay và phom dáng chỉn chu. CHAMÉA Nina hồng phấn có thân hình thang, quai cong mềm mại, nắp gập cổ điển và điểm nhấn kim loại ánh vàng.','Kết hợp váy trắng, áo blouse, chân váy midi; hoặc blazer kem và quần âu sáng màu.','Feminine Chic, Elegant Style và thời trang công sở.'],
 ['Satchel Mini – Cổ điển nhưng không lỗi thời','vera','Vera','Satchel Mini mang cấu trúc rõ ràng nhưng nhỏ gọn, phù hợp phong cách trẻ trung và chỉn chu. CHAMÉA Vera màu đỏ có thân chữ nhật bo góc, nắp gập tối giản, quai xách tay và dây đeo dài linh hoạt.','Phối cardigan, chân váy chữ A và giày Mary Jane; hoặc áo thun trắng với jeans xanh.','Vintage, Preppy và Smart Casual.'],
 ['Structured – Tuyên ngôn của sự thanh lịch','mila','Mila','Túi Structured tạo ấn tượng bởi phom dáng cứng cáp và đường nét sắc sảo. CHAMÉA Mila màu đen sở hữu dáng hình thang, nắp gập thanh lịch và khóa kim loại ánh vàng, phù hợp phong cách trưởng thành.','Kết hợp blazer, quần âu và loafer; hoặc váy midi đơn sắc với giày cao gót.','Quiet Luxury, Modern Classic và Business Chic.'],
 ['Quilted Chain – Điểm nhấn sang trọng đầy cuốn hút','perle','Perle','Túi Quilted Chain nổi bật với họa tiết chần trám và dây xích kim loại. CHAMÉA Perle màu đen có thân chữ nhật gọn gàng, bề mặt chần trám và dây xích ánh vàng tạo vẻ ngoài cuốn hút.','Phối váy đen, giày cao gót và trang sức tối giản; hoặc áo tweed, jeans và giày búp bê.','Classic Chic, Feminine và phong cách dự tiệc.']
 ];
 const get=n=>D.products.find(p=>p.id===n)||D.products.find(p=>p.id?.startsWith(n+'-'))||D.products.find(p=>p.name?.toLowerCase().includes(n));
 const link=n=>{const p=get(n);return p?'/san-pham/'+encodeURIComponent(p.id):'/tui-xach'};
 const picture=(n,caption)=>{const p=get(n);const originals={lune:'02-lune.png',nina:'03-nina.png',vera:'04-vera.png',mila:'05-mila.png',perle:'06-perle.png'};const original='/CHAMEA/assets/blog-top-5-2026/'+originals[n];const fallback=p?asset(p.image):'';return '<figure class="journal-figure"><a class="journal-photo-stage" href="'+link(n)+'"><img loading="lazy" src="'+original+'" onerror="this.onerror=null;this.src='+String.fromCharCode(39)+fallback+String.fromCharCode(39)+'" alt="Túi '+esc(n)+' CHAMÉA"></a><figcaption>'+esc(caption)+'</figcaption></figure>';};
 const productCard=n=>{const p=get(n);return p?'<aside class="journal-product"><img src="'+asset(p.image)+'" alt="'+esc(p.name)+'"><div><span>KHÁM PHÁ THIẾT KẾ</span><strong>CHAMÉA '+esc(n.charAt(0).toUpperCase()+n.slice(1))+'</strong><a href="/san-pham/'+p.id+'">Xem sản phẩm ↗</a></div></aside>':''};
 const headings=[['1. Xu hướng túi xách nữ 2026 có gì nổi bật?','xu-huong'],['2. TOP 5 kiểu dáng túi xách trendy 2026','top-5'],...entries.map((e,i)=>['2.'+(i+1)+'. Túi '+e[0],e[1]]),['3. Bí quyết lựa chọn kiểu túi xách phù hợp với phong cách','bi-quyet'],['3.1. Lựa chọn theo phong cách thời trang','phong-cach'],['3.2. Chọn kích thước phù hợp với nhu cầu','kich-thuoc'],['3.3. Ưu tiên màu sắc dễ phối đồ','chon-mau'],['4. Những gam màu túi xách đáng chú ý trong năm 2026','gam-mau'],['4.1. Đỏ Burgundy – Sang trọng và cuốn hút','burgundy'],['4.2. Hồng phấn – Dịu dàng và nữ tính','hong-phan'],['4.3. Đỏ cổ điển – Tự tin và nổi bật','do-co-dien'],['4.4. Đen kinh điển – Vẻ đẹp vượt thời gian','den'],['5. Câu hỏi thường gặp khi lựa chọn túi xách nữ','faq'],['6. CHAMÉA – Khi mỗi chiếc túi kể một câu chuyện phong cách','ket']];
 const h=(t,id,sub=false)=>'<h'+(sub?3:2)+' id="'+id+'">'+esc(t)+'</h'+(sub?3:2)+'>';
 const title='Top 5 mẫu túi xách nổi bật 2026 | CHAMÉA';

 // All editorial prose below is transcribed verbatim from the supplied Word document.
 const sourceSections=[{"title":"1. Xu hướng túi xách nữ 2026 có gì nổi bật?","content":"Xu hướng túi xách năm 2026 hướng đến sự cân bằng giữa tính ứng dụng và vẻ đẹp thời trang. Những thiết kế\nmang cảm hứng cổ điển được làm mới với phom dáng tinh tế, đường nét tối giản và các chi tiết kim loại nổi bật.\nBên cạnh những chiếc túi có cấu trúc cứng cáp, các mẫu túi đeo vai dáng ngang hay túi chần trám cũng mang đến\nnhiều lựa chọn thú vị. Đây là thời điểm để phái đẹp khám phá những thiết kế vừa hợp xu hướng, vừa thể hiện\nđược dấu ấn cá nhân."},{"title":"2. TOP 5 kiểu dáng túi xách trendy 2026","content":""},{"title":"2.1. Túi Baguette – Nét thanh lịch mang hơi thở hiện đại","content":"Túi Baguette là một trong những kiểu dáng mang đậm tinh thần thời trang hiện đại, nổi bật với thiết kế thuôn dài\ntheo chiều ngang cùng phần quai đeo vai gọn gàng. Lấy cảm hứng từ phong cách thời trang cuối thập niên 1990\nvà đầu những năm 2000, kiểu túi này tiếp tục được yêu thích nhờ vẻ đẹp tối giản nhưng không kém phần cuốn\nhút.\n\nTrong bộ sưu tập CHAMÉA, mẫu thiết kế Lune với màu đỏ burgundy gây ấn tượng với phom dáng ngang mềm\nmại, quai đeo thanh mảnh và chi tiết khóa kim loại ánh vàng nổi bật. Sự kết hợp giữa gam màu trầm ấm và những\nđường nét tinh tế mang đến vẻ ngoài vừa cổ điển vừa thời thượng.\nMẫu túi xách Lune của CHAMÉA với thiết kế hiện đại, nhỏ gọn là phụ kiện lí tưởng cho phái nữ khi kết hợp trang\nphục hằng ngày.\n\nGợi ý phối đồ: Kết hợp túi Baguette cùng áo sơ mi trắng, quần jeans ống đứng và giày cao gót để tạo phong cách\nthanh lịch. Với những buổi hẹn cuối tuần, nàng có thể phối túi cùng váy liền thân và giày búp bê để tăng thêm nét\nnữ tính.\n\nPhù hợp với: Những cô nàng yêu thích phong cách Minimalism, Quiet Luxury và Casual Chic."},{"title":"2.2. Túi Top Handle – Vẻ đẹp nữ tính và sang trọng","content":"Túi Top Handle luôn giữ một vị trí đặc biệt trong thế giới phụ kiện nhờ thiết kế quai xách tay đặc trưng và vẻ\nngoài thanh lịch. Không quá cầu kỳ, kiểu túi này tạo điểm nhấn bằng những đường nét cân đối, phom dáng chỉn\nchu và các chi tiết hoàn thiện tinh tế.\n\nMẫu túi Nina màu hồng phấn của CHAMÉA sở hữu phom dáng hình thang thanh thoát, phần quai xách cong\nmềm mại cùng thiết kế nắp gập cổ điển. Điểm nhấn kim loại ánh vàng và chi tiết trang trí đồng điệu giúp tổng thể\nchiếc túi trở nên tinh tế, nhẹ nhàng nhưng vẫn đầy cuốn hút.\n\n\n\n\nMẫu túi Nina của thương hiệu CHAMÉA với kiểu dáng Top Handle được yêu thích và ứng dụng trong nhiều dịp\nkhác nhau.\nGợi ý phối đồ: Một chiếc túi Top Handle màu hồng phấn sẽ trở nên nổi bật khi kết hợp cùng váy trắng, áo blouse\nhoặc chân váy midi. Nếu muốn tạo phong cách trưởng thành hơn, nàng có thể phối túi cùng blazer màu kem và\nquần âu sáng màu.\n\nPhù hợp với: Những cô nàng theo đuổi phong cách Feminine Chic, Elegant Style và thời trang công sở."},{"title":"2.3. Túi Satchel Mini – Cổ điển nhưng không lỗi thời","content":"Mang cảm hứng từ những chiếc túi Satchel truyền thống, phiên bản mini tạo nên sức hút nhờ thiết kế nhỏ gọn, cấu\ntrúc rõ ràng và vẻ ngoài thanh lịch. Đây là kiểu túi phù hợp với những cô gái yêu thích sự chỉn chu nhưng vẫn\nmuốn thể hiện nét trẻ trung trong phong cách hằng ngày.\n\nTrong các thiết kế của CHAMÉA, mẫu túi Vera màu đỏ nổi bật với phom dáng hình chữ nhật bo góc, phần nắp\ngập tối giản và quai xách tay mềm mại. Chi tiết tên thương hiệu ánh vàng trên thân túi tạo điểm nhấn tinh tế, trong\nkhi dây đeo dài giúp chiếc túi phù hợp với nhiều hoàn cảnh sử dụng.\nMẫu túi Vera với màu đỏ nổi bật là một trong những mẫu túi bán chạy nhất thương hiệu CHAMÉA trong năm\n2026.\n\nGợi ý phối đồ: Nàng có thể kết hợp túi Satchel Mini màu đỏ cùng áo cardigan, chân váy chữ A và giày Mary Jane\nđể tạo phong cách cổ điển. Với trang phục thường ngày, áo thun trắng và quần jeans xanh sẽ giúp chiếc túi trở\nthành điểm nhấn nổi bật.\n\nPhù hợp với: Những cô nàng yêu thích phong cách Vintage, Preppy và Smart Casual."},{"title":"2.4. Túi Structured – Tuyên ngôn của sự thanh lịch","content":"Nếu những thiết kế túi mềm mại mang đến cảm giác phóng khoáng, túi Structured lại chinh phục phái đẹp bằng vẻ\nngoài cứng cáp, đường nét sắc sảo và phom dáng rõ ràng.\n\nĐây là dòng túi đặc biệt phù hợp với những cô nàng yêu thích sự chuyên nghiệp, chỉn chu và phong cách thời\ntrang trưởng thành. Nhờ cấu trúc ổn định, túi Structured thường tạo cảm giác gọn gàng và giúp hoàn thiện những\nbộ trang phục có tính trang trọng.\n\nMẫu túi Mila màu đen của CHAMÉA sở hữu phom dáng hình thang, quai xách tay chắc chắn và thiết kế nắp gập\nthanh lịch. Chi tiết khóa kim loại ánh vàng ở trung tâm tạo điểm nhấn nổi bật trên nền túi đen, mang đến tổng thể\nsang trọng mà không quá cầu kỳ.\nSự kết hợp giữa màu đen kinh điển và thiết kế tối giản cũng giúp mẫu túi này dễ dàng đồng hành cùng nhiều\nphong cách khác nhau.\n\n\n\n\nMẫu túi Mila biểu tượng cho sự thanh lịch, mang phong cách hiện đại nhưng tối giản, là phụ kiện nên có trong bộ\nsưu tập túi xách của mọi cô nàng.\n\nGợi ý phối đồ: Kết hợp túi Structured màu đen cùng blazer, quần âu và giày loafer để tạo phong cách công sở\nhiện đại. Với những dịp đặc biệt, nàng có thể phối túi cùng váy midi đơn sắc và giày cao gót để tăng thêm nét\nthanh lịch.\n\nPhù hợp với: Những cô nàng yêu thích phong cách Quiet Luxury, Modern Classic và Business Chic."},{"title":"2.5. Túi Quilted Chain – Điểm nhấn sang trọng đầy cuốn hút","content":"Túi Quilted Chain là kiểu túi nổi bật với bề mặt chần trám và dây đeo xích kim loại đặc trưng. Sự kết hợp giữa\nhọa tiết hình học và những chi tiết ánh kim mang đến vẻ ngoài sang trọng, đồng thời tạo chiều sâu thị giác cho\nthiết kế.\n\nThiết kế túi Perle màu đen của CHAMÉA gây ấn tượng với họa tiết chần trám hình quả trám đều đặn, phần thân\ntúi hình chữ nhật gọn gàng và dây xích ánh vàng nổi bật. Sự tương phản giữa màu đen và sắc vàng tạo nên vẻ\nngoài cuốn hút, giúp chiếc túi dễ dàng trở thành điểm nhấn của tổng thể trang phục.\nMẫu túi Perle với họa tiết chần trám là một trong những mẫu túi thịnh hành nhất năm 2026 được các tín đồ thời\ntrang yêu thích\n\nGợi ý phối đồ: Phối túi Quilted Chain cùng váy đen, giày cao gót và trang sức tối giản để tạo phong cách sang\ntrọng cho buổi tiệc. Nếu muốn ứng dụng hằng ngày, nàng có thể kết hợp túi cùng áo tweed, quần jeans và giày\nbúp bê.\n\nPhù hợp với: Những cô nàng yêu thích phong cách Classic Chic, Feminine và thời trang dự tiệc."},{"title":"3. Bí quyết lựa chọn kiểu túi xách phù hợp với phong cách","content":"Giữa vô vàn thiết kế túi xách thời thượng, lựa chọn một chiếc túi phù hợp không chỉ phụ thuộc vào xu hướng mà\ncòn cần cân nhắc phong cách cá nhân và nhu cầu sử dụng."},{"title":"3.1. Lựa chọn theo phong cách thời trang","content":"Mỗi kiểu túi đều mang một nét đẹp riêng. Nếu yêu thích sự thanh lịch, nàng có thể ưu tiên túi Top Handle hoặc\nStructured. Trong khi đó, túi Baguette phù hợp với phong cách tối giản, túi Satchel Mini mang nét cổ điển và túi\nQuilted Chain tạo điểm nhấn sang trọng.\n\nHiểu rõ phong cách bản thân sẽ giúp nàng lựa chọn những thiết kế dễ kết hợp với tủ đồ hiện có."},{"title":"3.2. Chọn kích thước phù hợp với nhu cầu","content":"Một chiếc túi đẹp cần đáp ứng được những nhu cầu sử dụng thực tế. Nếu thường xuyên mang theo nhiều vật dụng,\nnàng nên ưu tiên những mẫu có không gian chứa đồ phù hợp. Ngược lại, túi cỡ nhỏ sẽ là lựa chọn lý tưởng cho\nnhững buổi hẹn hò hoặc dạo phố. Trước khi mua, hãy kiểm tra kích thước và các ngăn chứa để bảo đảm chiếc túi\ncó thể đồng hành cùng nàng một cách thuận tiện."},{"title":"3.3. Ưu tiên màu sắc dễ phối đồ","content":"Màu sắc ảnh hưởng trực tiếp đến khả năng ứng dụng của túi xách. Những gam màu trung tính như đen, kem và\nnâu thường dễ kết hợp với nhiều trang phục. Nếu muốn tạo điểm nhấn nổi bật, nàng có thể lựa chọn túi đỏ\nburgundy hoặc hồng phấn để làm mới phong cách hằng ngày."},{"title":"4. Những gam màu túi xách đáng chú ý trong năm 2026","content":"Bên cạnh kiểu dáng, màu sắc cũng là yếu tố góp phần tạo nên sức hút của một chiếc túi xách. Trong năm 2026,\nnhững gam màu mang vẻ đẹp tinh tế và có khả năng ứng dụng linh hoạt tiếp tục là lựa chọn đáng chú ý."},{"title":"4.1. Đỏ Burgundy – Sang trọng và cuốn hút","content":"Đỏ burgundy mang đến vẻ đẹp trưởng thành, quyến rũ nhưng không quá nổi bật. Gam màu này đặc biệt phù hợp\nvới những thiết kế túi đeo vai dáng ngang, giúp tạo điểm nhấn tinh tế cho trang phục trung tính."},{"title":"4.2. Hồng phấn – Dịu dàng và nữ tính","content":"Hồng phấn là lựa chọn lý tưởng cho những cô nàng yêu thích phong cách nhẹ nhàng. Khi kết hợp cùng các thiết\nkế túi Top Handle, gam màu này càng làm nổi bật nét thanh lịch và mềm mại."},{"title":"4.3. Đỏ cổ điển – Tự tin và nổi bật","content":"Một chiếc túi màu đỏ có thể trở thành điểm nhấn ấn tượng cho bộ trang phục. Đặc biệt, khi kết hợp cùng kiểu\ndáng Satchel Mini, màu đỏ mang đến sự giao thoa giữa vẻ đẹp cổ điển và tinh thần thời trang hiện đại."},{"title":"4.4. Đen kinh điển – Vẻ đẹp vượt thời gian","content":"Đen luôn là một trong những gam màu có tính ứng dụng cao trong thế giới phụ kiện. Từ túi Structured thanh lịch\nđến túi Quilted Chain sang trọng, sắc đen giúp tôn lên đường nét thiết kế và dễ dàng kết hợp với nhiều phong\ncách."},{"title":"5. Câu hỏi thường gặp khi lựa chọn túi xách nữ","content":""},{"title":"5.1. Kiểu túi xách nào phù hợp với phong cách thanh lịch?","content":"Túi Top Handle và Structured là hai lựa chọn đáng cân nhắc nhờ thiết kế chỉn chu, phom dáng rõ ràng và khả\nnăng kết hợp linh hoạt với trang phục công sở hoặc váy áo nữ tính."},{"title":"5.2. Nên lựa chọn túi xách màu đen hay màu nổi bật?","content":"Nếu ưu tiên khả năng sử dụng hằng ngày, túi màu đen thường dễ phối đồ hơn. Tuy nhiên, những gam màu như đỏ\nburgundy, đỏ cổ điển hoặc hồng phấn sẽ phù hợp nếu nàng muốn tạo điểm nhấn và thể hiện cá tính riêng."},{"title":"5.3. Túi Baguette và túi Satchel Mini khác nhau như thế nào?","content":"Túi Baguette thường có thiết kế thuôn dài theo chiều ngang, quai đeo vai ngắn và phom dáng gọn gàng. Trong khi\nđó, túi Satchel Mini thường có cấu trúc rõ ràng hơn, quai xách tay và có thể đi kèm dây đeo dài."},{"title":"5.4. Túi Quilted Chain có phù hợp để sử dụng hằng ngày không?","content":"Có. Bên cạnh những dịp đặc biệt, túi Quilted Chain hoàn toàn có thể kết hợp cùng trang phục thường ngày như áo\nsơ mi, quần jeans hoặc chân váy. Nàng nên cân nhắc kích thước, trọng lượng dây xích và mức độ thoải mái khi\nđeo."},{"title":"5.5. Làm thế nào để lựa chọn một chiếc túi không nhanh lỗi mốt?","content":"Hãy ưu tiên những thiết kế có phom dáng cân đối, màu sắc dễ kết hợp và phù hợp với phong cách cá nhân. Một\nchiếc túi đáp ứng tốt nhu cầu sử dụng thường có giá trị lâu dài hơn so với việc chỉ lựa chọn theo xu hướng nhất\nthời."},{"title":"6. CHAMÉA – Khi mỗi chiếc túi kể một câu chuyện phong cách","content":"Mỗi chiếc túi xách đều mang một nét đẹp riêng, cũng giống như cách mỗi cô gái thể hiện cá tính và gu thẩm mỹ\ncủa mình. Có người yêu thích vẻ thanh lịch của túi Structured, có người bị thu hút bởi nét nữ tính của Top Handle,\ntrong khi những thiết kế Baguette, Satchel Mini hay Quilted Chain lại mang đến những nguồn cảm hứng khác\nbiệt.\n\nDù xu hướng thời trang liên tục thay đổi, một chiếc túi phù hợp vẫn luôn là người bạn đồng hành giúp nàng tự tin\nthể hiện phong cách riêng.\n\nKhám phá những thiết kế túi xách tại CHAMÉA và tìm kiếm chiếc túi dành riêng cho câu chuyện thời\ntrang của bạn."}];
 const clean=s=>s.replace(/\s*\n\s*/g,' ').replace(/\s+/g,' ').trim();
 const para=s=>'<p>'+esc(clean(s))+'</p>';
 const paragraphs=s=>s.split(/\n\s*\n+/).map(clean).filter(Boolean);
 let body='';
 sourceSections.forEach((section,i)=>{
  const title=section.title;
  const sub=/^[2-5]\.\d\./.test(title);
  const id=i===0?'xu-huong':i===1?'top-5':i>=2&&i<=6?entries[i-2][1]:i===7?'bi-quyet':i===8?'phong-cach':i===9?'kich-thuoc':i===10?'chon-mau':i===11?'gam-mau':i===12?'burgundy':i===13?'hong-phan':i===14?'do-co-dien':i===15?'den':i===16?'faq':i===22?'ket': 'faq-'+(i-16);
  if(i>=17&&i<=21)return;
  body+=h(title,id,sub);
  if(i===16){
   body+='<div class="journal-faq-list">';
   sourceSections.slice(17,22).forEach((faq,j)=>{body+='<details class="journal-faq-item" '+(j===0?'open':'')+'><summary id="faq-'+(j+1)+'"><span>'+esc(faq.title.replace(/^5\.\d\.\s*/,''))+'</span><span class="journal-faq-sign" aria-hidden="true"></span></summary><div class="journal-faq-answer">'+paragraphs(faq.content).map(para).join('')+'</div></details>'});
   body+='</div>';return;
  }
  // Word places figure captions inline with body paragraphs in some sections.
  // Split on the exact caption beginning and the next "Gợi ý phối đồ:" heading,
  // so styling applies only to the caption, never to the following prose.
  const captionStarts=[
   'Mẫu túi xách Lune của CHAMÉA',
   'Mẫu túi Nina của thương hiệu CHAMÉA',
   'Mẫu túi Vera với màu đỏ nổi bật',
   'Mẫu túi Mila biểu tượng cho sự thanh lịch',
   'Mẫu túi Perle với họa tiết chần trám'
  ];
  const captionStart=i>=2&&i<=6?captionStarts[i-2]:null;
  const source=section.content;
  const at=captionStart?source.indexOf(captionStart):-1;
  if(at>=0){
   const next=source.indexOf('Gợi ý phối đồ:',at);
   const stop=next>=0?next:source.length;
   const before=source.slice(0,at).trim();
   const caption=source.slice(at,stop).trim();
   const after=source.slice(stop).trim();
   paragraphs(before).forEach(p=>body+=para(p));
   body+=picture(entries[i-2][1],caption);
   paragraphs(after).forEach(p=>body+=para(p));
  }else{
   paragraphs(source).forEach(p=>body+=para(p));
   if(captionStart)body+=picture(entries[i-2][1],'');
  }
  if(i>=2&&i<=6)body+=productCard(entries[i-2][1]);
 });
 const toc=headings.map((x,i)=>'<a class="'+([0,1,7,11,16,17].includes(i)?'journal-toc-major':'journal-toc-sub')+'" href="#'+x[1]+'">'+esc(x[0])+'</a>').join('')+sourceSections.slice(17,22).map((x,i)=>'<a class="journal-toc-sub" href="#faq-'+(i+1)+'">5.'+(i+1)+'. '+esc(x.title)+'</a>').join('');

 const featuredArticles=[
 {title:'TOP 5 mẫu túi tote đẹp và chất lượng đáng mua năm 2026',category:'Kiến thức thời trang',image:'chamea-tote-blog-cover-new.webp',href:'/goc-chon-qua/top-5-tui-tote-2026'},
 {title:'Bí kíp chọn quà ưng ý cho người thương 20/10: 7 gợi ý tinh tế gửi trọn yêu thương',category:'CHAMÉA Journal',image:'/CHAMEA/assets/blog-qua-tang-20-10/chamea-blog-20-10-cover-new.webp',href:'/goc-chon-qua/bi-kip-chon-qua-20-10'},
 {title:'Top 5 mẫu túi xách nổi bật 2026',category:'Kiến thức thời trang',image:'/CHAMEA/assets/blog-top-5-2026/01-anh-bia-chamea.png',href:'/goc-chon-qua/top-5-mau-tui-xach-noi-bat-2026'}
].filter(x=>x.href!=='/goc-chon-qua/'+location.pathname.split('/').filter(Boolean).pop());
 const featuredList='<section class="journal-featured"><h2>Bài viết nổi bật <span aria-hidden="true">⌄</span></h2>'+featuredArticles.map((x,i)=>'<a class="journal-featured-item" href="'+x.href+'"><span class="journal-featured-index">'+(i+1)+'</span><span class="journal-featured-thumb"><img src="'+asset(x.image)+'" loading="lazy" alt="'+esc(x.title)+'"></span><span class="journal-featured-info"><strong>'+esc(x.title)+'</strong><small>'+esc(x.category)+'</small></span></a>').join('')+'</section>';
 const related=chameaJournalRelated('top-5-mau-tui-xach-noi-bat-2026');
 const productList=entries.map(e=>get(e[1])).filter(Boolean);
 const recommend=(label,items)=>'<section class="journal-recommend"><div class="journal-recommend-head"><div><span>CHAMÉA EDITOR\'S PICKS</span><h2>'+label+'</h2></div><a href="/tui-xach">Xem tất cả ↗</a></div><div class="journal-recommend-rail">'+items.map(p=>'<a class="journal-mini-product" href="/san-pham/'+p.id+'"><span class="journal-mini-image"><img src="'+asset(p.image)+'" alt="'+esc(p.name)+'" loading="lazy">'+(hasDiscount(p)?'<em>−20%</em>':'')+'</span><span class="journal-mini-name">'+esc(p.name)+'</span><span class="journal-mini-price">'+money(price(p))+'</span><span class="journal-mini-link">Xem túi ↗</span></a>').join('')+'</div></section>';

 // Auto-link every product name mentioned in editorial copy, as in the tote article.
 // Avoid adding nested links inside product cards, photos or existing anchors.
 const linkProductMentions=html=>{
  const holder=document.createElement('div');holder.innerHTML=html;
  const walker=document.createTreeWalker(holder,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  const re=/\b(?:CHAMÉA\s+)?(?:Lune|Nina|Vera|Mila|Perle)\b/gi;
  for(const node of nodes){
   if(node.parentElement?.closest('a,script,style,button,figcaption,summary'))continue;
   const raw=node.nodeValue;re.lastIndex=0;if(!re.test(raw))continue;re.lastIndex=0;
   const fragment=document.createDocumentFragment();let last=0,m;
   while((m=re.exec(raw))!==null){
    if(m.index>last)fragment.appendChild(document.createTextNode(raw.slice(last,m.index)));
    const name=entries.find(e=>m[0].toLowerCase().endsWith(e[2].toLowerCase()));
    const product=name&&get(name[1]);
    if(product){const a=document.createElement('a');a.href='/san-pham/'+encodeURIComponent(product.id);a.className='journal-inline-product';a.textContent=m[0];a.title='Xem túi '+name[2];fragment.appendChild(a)}
    else fragment.appendChild(document.createTextNode(m[0]));
    last=m.index+m[0].length;
   }
   if(last<raw.length)fragment.appendChild(document.createTextNode(raw.slice(last)));
   node.replaceWith(fragment);
  }
  return holder.innerHTML;
 };
 body=linkProductMentions(body);
 body=body.replace('<h2 id="bi-quyet">',recommend('Gợi ý sản phẩm từ CHAMÉA',productList)+'<h2 id="bi-quyet">');
 body=body.replace('<h2 id="faq">',recommend('Những thiết kế nàng có thể thích',productList.slice().reverse())+'<h2 id="faq">');
 const cover=get('lune');
 const coverSrc='/CHAMEA/assets/blog-top-5-2026/01-anh-bia-chamea.png';const coverFallback=cover?asset(cover.image):'';
