function article(a){return `<article class="article-body"><p class="eyebrow">GÓC CHỌN QUÀ · CHAMÉA</p><h1>${a.title}</h1><p class="muted">${a.summary}</p><img src="${asset(a.image)}" alt="Ảnh túi CHAMÉA minh họa bài viết">${a.sections.map(([h,t])=>`<h2>${h}</h2><p>${t}</p>`).join('')}<p class="demo-note">Nội dung biên tập theo brief CHAMÉA và ảnh chiến dịch được cung cấp. Tên và giá sản phẩm là minh họa.</p>${link('/goi-y-chon-qua','Tìm chiếc túi phù hợp '+icon('arrow'))}</article>`}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d')}
function route(){const path=(location.pathname.replace(/^\/CHAMEA(?=\/|$)/,'').replace(/\/$/,'').replace('/index.html','')||'/');if(path==='/')return ['CHAMÉA – Món Quà Cho Người Bạn Trân Trọng',home()];if(path==='/tui-xach')return ['Túi xách',catalog()];if(path==='/bo-suu-tap')return ['Bộ sưu tập',collections()];if(path==='/qua-tang-20-10'||path==='/bo-suu-tap/qua-tang-20-10')return ['Quà tặng 20/10',campaignLanding()];if(path.startsWith('/bo-suu-tap/')){const c=D.collections.find(x=>path.endsWith('/'+x.id));if(c)return [c.name,c.id==='20-10'?campaignLanding():catalog(c)]}if(path.startsWith('/san-pham/')){const p=product(path.split('/')[2]);if(p)return [p.name,productPage(p)]}if(path==='/goi-y-chon-qua')return ['Gợi ý chọn quà',giftPage()];if(path==='/goc-chon-qua')return ['Blog',blogPage()];if(path==='/goc-chon-qua/bi-kip-chon-qua-20-10')return ['Bí kíp chọn quà 20/10',gift2010Journal()];if(path==='/goc-chon-qua/top-5-mau-tui-xach-noi-bat-2026')return ['Top 5 mẫu túi xách nổi bật 2026',handbags2026Journal()];if(path==='/goc-chon-qua/top-5-tui-tote-2026')return ['Top 5 mẫu túi tote CHAMÉA 2026',toteJournal()];if(path==='/gio-hang')return ['Giỏ hàng',cartPage()];if(path==='/thanh-toan')return ['Thanh toán mô phỏng',checkout()];if(path==='/don-hang-mau')return ['Đơn hàng mẫu',resultPage()];if(path==='/ve-chamea')return ['Về CHAMÉA',about()];if(path==='/lien-he')return ['Liên hệ',contact()];if(path==='/yeu-thich')return ['Yêu thích',pageHead('Những thiết kế bạn yêu thích','Lưu một nét riêng, để trở lại khi bạn sẵn sàng.')+`<div class="container section">${favs.length?`<div class="grid">${cards(D.products.filter(p=>favs.includes(p.id)))}</div>${note}`:empty('Chưa có túi yêu thích','Chạm vào biểu tượng trái tim trên mẫu bạn thích.','/tui-xach','Khám phá túi xách')}</div>`];if(path.startsWith('/chinh-sach/')){const id=path.split('/')[2];if(policyNames[id])return [policyNames[id],policy(id)]}if(path.startsWith('/goc-chon-qua/')){const a=D.articles.find(x=>path.endsWith('/'+x.id));if(a)return [a.title,article(a)]}return ['Không tìm thấy trang',pageHead('Trang này chưa có')+empty('Cùng trở lại khám phá CHAMÉA','Đường dẫn có thể chưa chính xác.','/','Về trang chủ')]}
function render(scroll=true){applyDesign();header();const [title,html]=route();const viewedPath=location.pathname.replace(/^\/CHAMEA(?=\/|$)/,'');if(viewedPath.startsWith('/san-pham/')){const viewedProduct=product(viewedPath.split('/')[2]);if(viewedProduct)recordRecentlyViewed(viewedProduct.id)}document.title=title.startsWith('CHAMÉA –')?title:title+' | CHAMÉA';$('#main').innerHTML=html;document.querySelector('body > .journal-toc-float')?.remove();const floatingToc=$('#main .journal-toc-float');if(floatingToc)document.body.appendChild(floatingToc);if(!$('#main h1'))$('#main').insertAdjacentHTML('afterbegin',`<h1 class="sr-only">${esc(title)}</h1>`);applyOverrides();applySiteExtras();$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}}

// Product card angle rotation and mouse-drag rails. Event delegation survives SPA renders.
const chameaAngleTimers=new WeakMap();
const chameaAnglePreloaded=new Set();
function chameaPreloadAngles(card){let files;try{files=JSON.parse(card.dataset.images||'[]')}catch{return}for(const file of files){const url=asset(file);if(chameaAnglePreloaded.has(url))continue;chameaAnglePreloaded.add(url);const image=new Image();image.src=url}}

function chameaSetAngle(card,index){let files;try{files=JSON.parse(card.dataset.images||'[]')}catch{return}if(!files.length)return;const image=card.querySelector('img');if(!image)return;const i=index%files.length;image.src=asset(files[i]);image.style.objectPosition=card.dataset.collage==='1'?['left','center','right'][i]+' center':'center';const indicator=card.querySelector('.chamea-angle-indicator');if(indicator)indicator.textContent=String(i+1).padStart(2,'0')+' / '+String(files.length).padStart(2,'0')}
function chameaStopAngle(card){if(!card)return;const timer=chameaAngleTimers.get(card);if(timer)clearInterval(timer);chameaAngleTimers.delete(card);chameaSetAngle(card,0);card.classList.remove('angle-active')}
document.addEventListener('pointerover',event=>{if(event.pointerType==='touch')return;const card=event.target.closest?.('.chamea-angle-card');if(!card||chameaAngleTimers.has(card))return;let files;try{files=JSON.parse(card.dataset.images||'[]')}catch{return}if(files.length<2)return;let i=0;card.classList.add('angle-active');chameaPreloadAngles(card);chameaSetAngle(card,++i);chameaAngleTimers.set(card,setInterval(()=>chameaSetAngle(card,++i),280))});
document.addEventListener('pointerout',event=>{const card=event.target.closest?.('.chamea-angle-card');if(card&&!card.contains(event.relatedTarget))chameaStopAngle(card)});
document.addEventListener('focusin',event=>{const card=event.target.closest?.('.chamea-angle-card');if(card&&matchMedia('(prefers-reduced-motion: reduce)').matches===false){let files;try{files=JSON.parse(card.dataset.images||'[]')}catch{return}if(files.length<2||chameaAngleTimers.has(card))return;let i=0;card.classList.add('angle-active');chameaPreloadAngles(card);chameaSetAngle(card,++i);chameaAngleTimers.set(card,setInterval(()=>chameaSetAngle(card,++i),280))}});
document.addEventListener('focusout',event=>{const card=event.target.closest?.('.chamea-angle-card');if(card)chameaStopAngle(card)});
let chameaRailDrag=null;
document.addEventListener('pointerdown',event=>{const rail=event.target.closest?.('.chamea-product-rail');if(!rail||event.pointerType==='touch'||event.button!==0)return;chameaRailDrag={rail,x:event.clientX,left:rail.scrollLeft,moved:false}});
document.addEventListener('pointermove',event=>{if(!chameaRailDrag)return;const d=event.clientX-chameaRailDrag.x;if(Math.abs(d)>6){chameaRailDrag.moved=true;chameaRailDrag.rail.scrollLeft=chameaRailDrag.left-d;chameaRailDrag.rail.classList.add('is-dragging')}});
document.addEventListener('pointerup',()=>{if(!chameaRailDrag)return;const rail=chameaRailDrag.rail,moved=chameaRailDrag.moved;rail.classList.remove('is-dragging');chameaRailDrag=null;if(moved){rail.dataset.suppressClick='1';setTimeout(()=>delete rail.dataset.suppressClick,150)}});
// Explicit per-photo hover state: lift the image and restore its exact staggered position on exit.
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const photo=e.target.closest?.('.chamea-friends-photo');if(photo&&!photo.contains(e.relatedTarget))photo.classList.add('is-lifted')});
document.addEventListener('pointerout',e=>{const photo=e.target.closest?.('.chamea-friends-photo');if(photo&&!photo.contains(e.relatedTarget))photo.classList.remove('is-lifted')});
document.addEventListener('pointerdown',e=>{const photo=e.target.closest?.('.chamea-friends-photo');if(photo)photo.classList.remove('is-lifted')});
// Community rail: edge hover auto-scroll, mouse drag and native touch swipe.
let chameaFriendsDrag=null,chameaFriendsHover=null,chameaFriendsRaf=0;
function chameaFriendsStop(){chameaFriendsHover=null;if(chameaFriendsRaf){cancelAnimationFrame(chameaFriendsRaf);chameaFriendsRaf=0}}
function chameaFriendsTick(){const h=chameaFriendsHover;if(!h||!h.rail.isConnected||chameaFriendsDrag||matchMedia('(prefers-reduced-motion: reduce)').matches){chameaFriendsStop();return}const rail=h.rail,rect=rail.getBoundingClientRect(),edge=Math.min(170,rect.width*.24),x=h.x-rect.left;const velocity=x<edge?-(edge-x)/edge*9:x>rect.width-edge?(x-(rect.width-edge))/edge*9:0;rail.scrollLeft+=velocity;chameaFriendsRaf=requestAnimationFrame(chameaFriendsTick)}
document.addEventListener('pointermove',e=>{const rail=e.target.closest?.('.chamea-friends-rail');if(chameaFriendsDrag){const d=e.clientX-chameaFriendsDrag.x;if(Math.abs(d)>5){chameaFriendsDrag.moved=true;chameaFriendsDrag.rail.classList.add('is-dragging')}chameaFriendsDrag.rail.scrollLeft=chameaFriendsDrag.left-d;return}if(e.pointerType==='touch'||!rail){chameaFriendsStop();return}chameaFriendsHover={rail,x:e.clientX};if(!chameaFriendsRaf)chameaFriendsRaf=requestAnimationFrame(chameaFriendsTick)});
document.addEventListener('pointerdown',e=>{const rail=e.target.closest?.('.chamea-friends-rail');if(!rail||e.pointerType==='touch'||e.button!==0)return;chameaFriendsStop();chameaFriendsDrag={rail,x:e.clientX,left:rail.scrollLeft,moved:false}});
document.addEventListener('pointerup',()=>{if(!chameaFriendsDrag)return;chameaFriendsDrag.rail.classList.remove('is-dragging');chameaFriendsDrag=null});
document.addEventListener('pointercancel',()=>{chameaFriendsDrag?.rail.classList.remove('is-dragging');chameaFriendsDrag=null;chameaFriendsStop()});
document.addEventListener('pointerleave',e=>{if(e.target?.classList?.contains('chamea-friends-rail'))chameaFriendsStop()},true);
document.addEventListener('click',event=>{const rail=event.target.closest?.('.chamea-product-rail');if(rail?.dataset.suppressClick==='1'){event.preventDefault();event.stopPropagation()}},true);

function go(url,scroll=true){closePanel();const target=url.startsWith('/CHAMEA/')?url:url.startsWith('/')?'/CHAMEA'+url:url;history.pushState({},'',target);selectedQty=1;galleryIndex=0;render(scroll)}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function openPanel(title,html,wide=false){panelFocus=document.activeElement;const panel=$('#panel');panel.classList.toggle('wide-panel',wide);panel.innerHTML=`<div class="panel-head"><h2 id="panel-title">${title}</h2><button class="panel-close" data-action="close" aria-label="Đóng">×</button></div>${html}`;if(!panel.open)panel.showModal();document.body.style.overflow='hidden'}
function closePanel(){if($('#panel').open)$('#panel').close();if($('#zoom').open)$('#zoom').close();document.body.style.overflow=''}
function cartPanel(){openPanel(`Giỏ hàng (${count()})`,cart.length?`${cart.map(x=>cartRow(x)).join('')}${totals()}<div class="panel-actions">${link('/gio-hang','Xem giỏ hàng','btn outline')}${link('/thanh-toan','Tiếp tục thanh toán '+icon('arrow'))}</div><p class="demo-note">Thanh toán mô phỏng — không phát sinh giao dịch.</p>`:empty('Giỏ hàng đang trống','Một chiếc túi phù hợp đang chờ bạn.','/tui-xach','Khám phá túi xách'))}
function updateCart(){persist('chamea-cart-v1',cart);header();if($('#panel').open)cartPanel();if(location.pathname==='/gio-hang'||location.pathname==='/thanh-toan')render(false)}
function addCart(id,qty){const existing=cart.find(x=>x.id===id);if(existing)existing.qty=Math.min(99,existing.qty+qty);else cart.push({id,qty:Math.min(99,qty)});persist('chamea-cart-v1',cart);header()}
function refreshQuiz(){const host=$('#quiz-host');if(host)host.innerHTML=quizHTML()}
function showSearch(q=''){const matches=D.products.filter(p=>normalize(p.name+' '+p.color+' '+p.shape).includes(normalize(q)));$('#search-results').innerHTML=q.trim()?`<p class="small muted">${matches.length} kết quả</p>${matches.map(p=>`<a class="search-result" href="/san-pham/${p.id}"><img src="${asset(p.image)}" alt="${p.name}"><div><p>${p.name}</p>${priceHTML(p)}</div>${icon('arrow')}</a>`).join('')||'<p>Không tìm thấy sản phẩm. Thử “kem”, “tím” hoặc “đeo vai”.</p>'}`:'<p class="small muted">Gợi ý: kem, tím mận, túi đeo vai.</p>'}
// Journal TOC stays in the viewport while scrolling and can be repositioned by dragging its handle.
let journalTocDrag=null;
let journalTocIgnoreClick=false;
document.addEventListener('pointerdown',e=>{
 const handle=e.target.closest?.('body > .journal-toc-float .journal-toc-toggle');
 if(!handle||e.button!==0)return;
 const root=handle.closest('.journal-toc-float'),rect=root.getBoundingClientRect();
 journalTocDrag={root,handle,pointerId:e.pointerId,x:e.clientX,y:e.clientY,left:rect.left,top:rect.top,moved:false};
});
document.addEventListener('pointermove',e=>{
 const d=journalTocDrag;if(!d||e.pointerId!==d.pointerId)return;
 const dx=e.clientX-d.x,dy=e.clientY-d.y;
 if(!d.moved&&Math.hypot(dx,dy)<7)return;
 d.moved=true;
 const left=Math.max(6,Math.min(innerWidth-54,d.left+dx));
 const top=Math.max(8,Math.min(innerHeight-56,d.top+dy));
 d.root.style.setProperty('left',left+'px','important');
 d.root.style.setProperty('top',top+'px','important');
 d.root.style.setProperty('bottom','auto','important');
 d.root.classList.toggle('journal-toc-flip',left>innerWidth-390);
 e.preventDefault();
},{passive:false});
function endJournalTocDrag(e){
 const d=journalTocDrag;if(!d||e.pointerId!==d.pointerId)return;
 if(d.moved){journalTocIgnoreClick=true;setTimeout(()=>{journalTocIgnoreClick=false},100)}
 journalTocDrag=null;
}
document.addEventListener('pointerup',endJournalTocDrag);
document.addEventListener('pointercancel',endJournalTocDrag);
