function applySiteExtras(){const cfg=window.EDITOR_DEFAULTS||{},site=cfg.site||{},theme=cfg.theme||{};const head=document.querySelector('.announcement');if(head){head.textContent=site.announcement||'CHAMÉA — Chạm đúng người · Trao đúng quà';head.style.display=Number(site.announcementEnabled)===0?'none':''}const note=document.querySelector('.head-note');if(note&&site.headerNote)note.textContent=site.headerNote;document.querySelectorAll('.chamea-extras').forEach(n=>n.remove());document.documentElement.classList.remove('chamea-pattern-on');const main=document.querySelector('#main');if(!main)return;const isHome=['/','/CHAMEA','/CHAMEA/'].includes(location.pathname);document.documentElement.classList.toggle('chamea-pattern-on',Boolean(site.patternImage)&&Number(site.patternEnabled)!==0);document.documentElement.classList.toggle('chamea-inner-page',!isHome);if(!isHome)return;const wrap=document.createElement('section');wrap.className='chamea-extras';let html='';const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.documentElement.classList.toggle('chamea-pattern-on',Boolean(site.patternImage)&&Number(site.patternEnabled)!==0);if(Number(site.benefitsEnabled)!==0&&(site.offerTitle||site.shippingTitle)){html+='<div class="chamea-benefits">';if(site.offerTitle)html+='<div><strong>'+safe(site.offerTitle)+'</strong><p>'+safe(site.offerDescription||'')+'</p>'+(site.couponCode?'<small>Mã: '+safe(site.couponCode)+'</small>':'')+'</div>';if(site.shippingTitle)html+='<div><strong>'+safe(site.shippingTitle)+'</strong><p>'+safe(site.shippingDescription||'')+'</p>'+(Number(site.freeShippingThreshold)>0?'<small>Miễn phí từ '+Number(site.freeShippingThreshold).toLocaleString('vi-VN')+' ₫</small>':'')+'</div>';html+='</div>'}wrap.innerHTML=html;if(html){const sections=main.querySelectorAll('section');const anchor=sections.length>2?sections[1]:null;if(anchor&&anchor.parentNode===main)main.insertBefore(wrap,anchor.nextSibling);else main.append(wrap)}document.documentElement.style.setProperty('--chamea-desktop-cols',Math.max(1,Math.min(6,Number(theme.desktopColumns)||3)));document.documentElement.style.setProperty('--chamea-tablet-cols',Math.max(1,Math.min(5,Number(theme.tabletColumns)||2)));document.documentElement.style.setProperty('--chamea-mobile-cols',Math.max(1,Math.min(3,Number(theme.mobileColumns)||2)))}
